        var plan = PlanCopiedRails(rails, buildSolids);

        string report = string.Join(System.Environment.NewLine, plan.Report.Select(entry => entry.ToString()));
        Assert.True(plan.Walls.Count > 0, report);
        Assert.DoesNotContain(plan.Report, entry => entry.Level == RetainingWallPlannerCore.ReportLevel.Error);
        return plan;
    }

    private static RetainingWallPlannerCore.PlanResult PlanCopiedRails(RetainingWallPlannerCore.RailPolyline?[] rails, bool buildSolids)
    {
        if (buildSolids)
            throw new InvalidOperationException("The copied benchmark fixture is stored as native-free rail polylines and cannot build Rhino Breps.");

        return RetainingWallPlannerCore.PlanPolylines(
            rails,
            1,
            curveParsingTolerance: 0.005,
            buildSolids: false);
    }
